), ins as (
  insert into public.posts (account_id, location_id, platform, external_id, published_at, media_type, caption, permalink, duration_sec, source)
  select a.id, s.loc, s.platform, s.external_id, s.published_at::timestamptz, s.media_type, s.caption, s.permalink, s.duration_sec::numeric, 'import'
  from src s join public.social_accounts a on a.location_id = s.loc and a.platform = s.platform
  on conflict (account_id, external_id) do update set caption = excluded.caption
  returning id, account_id, external_id
)
insert into public.post_metrics (post_id, captured_on, views, reach, likes, comments, shares, saves, follows, clicks,
                                 total_interactions, watch_time_total_sec, watch_time_avg_sec)
select i.id, s.captured_on::date, s.views, s.reach, s.likes, s.comments, s.shares, s.saves, s.follows, s.clicks,
       s.total, s.wt::numeric, s.wa::numeric
from ins i
join public.social_accounts a on a.id = i.account_id
join src s on s.external_id = i.external_id and s.loc = a.location_id and s.platform = a.platform
on conflict (post_id, captured_on) do nothing;
